UPDATE storage_buckets
SET used_storage = used_storage + #{size}
WHERE id = #{bucketId}
  AND owner_id = #{ownerId}
  AND status = 1
  AND #{size} <= total_storage
  AND used_storage <= total_storage - #{size}

UPDATE storage_buckets
SET used_storage = CASE
    WHEN used_storage > #{size} THEN used_storage - #{size}
    ELSE 0
END
WHERE id = #{bucketId}
